func handler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		log.Println(err)
		return nil, fmt.Errorf("failed to create session: %v", err)
	}

	ec2Svc := ec2.New(sess)

	// Filter EBS snapshots by the "backup_type" tag and retention policy
	shouldDelete := func(snapshot *ec2.Snapshot) bool {
		tag, ok := snapshot.Tags["backup_type"]
		if !ok {
			return false
		}
		value := *tag.Value

		switch value {
		case "monthly":
			return len(snapshot.snapshots) > 14
		case "daily":
			return len(snapshot.snapshots) > 10
		case "weekly":
			return len(snapshot.snapshots) > 4
		case "yearly":
			return true
		default:
			return false
		}
	}

	// List all EBS snapshots
	snapshots, err := ec2Svc.DescribeSnapshots(&ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("tag:backup_type"),
				Values: []*string{
					aws.String("monthly"),
					aws.String("daily"),
					aws.String("weekly"),
					aws.String("yearly"),
				},
			},
		},
	})
	if err != nil {
		log.Println(err)
		return nil, fmt.Errorf("failed to list snapshots: %v", err)
	}

	// Delete snapshots that should be deleted
	for _, snapshot := range snapshots.Snapshots {
		if shouldDelete(snapshot) {
			_, err := ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: aws.String(*snapshot.SnapshotId),
			})
			if err != nil {
				log.Println(err)
			}
		}
	}

	return nil, nil
}

func main() {
	lambda.Start(handler)
}
